import { renderPreact, isDarkMode, setTheme } from './utils';

import { isSameDay } from '../../shared';
import { getStorageItems, removeStorageItems } from '../../shared/chromeApi';
import Widget from './components/Widget';
import renderTiles from './components/Tiles/render';
import renderSidebar from './components/Sidebar/render';
import renderCounter from './components/Counter/render';
import { ContentAds, SearchTuple } from './interfaces';
import { FeatureFlags, UserState } from '../../newtab/features/user/slice/types';

import {
  matchDigidip,
  matchAdNet,
  matchAdmarketplace,
  matchSiteplug,
  matchZeropark,
} from './api'
import { TilesState } from '../../newtab/features/tiles/slice/types';

const theme = {
  dark: {
    '--oh-text-color-main': '#bdc1c6',
    '--oh-text-color-dark': '#e8eaed',
    '--oh-text-color-light': '#9aa0a6',
    '--oh-link-color': '#8ab4f8',
    '--oh-brand-color': '#fff',
  },
  light: {
    '--oh-text-color-main': '#202124',
    '--oh-text-color-dark': '#000000',
    '--oh-text-color-light': '#4E5156',
    '--oh-link-color': '#1366FB',
    '--oh-brand-color': '#226ffb',
  }
}

const renderWidget = async (): Promise<void> => {
  const dOMContentLoaded = new Promise((resolve) => {
    if (['complete', 'interactive', 'loaded'].includes(document.readyState)) {
      return resolve(null);
    }

    window.addEventListener('DOMContentLoaded', resolve);
  });

  const search = new URLSearchParams(location.search);
  if (search.get('tbm')) return null;

  const { contentAds, annotations, user, yieldkitDomains, zp } = await getStorageItems<{
    contentAds: ContentAds,
    annotations,
    user: UserState,
    yieldkitDomains,
    zp,
    tiles: TilesState
  }>([
    'contentAds',
    'annotations',
    'user',
    'yieldkitDomains',
    'zp',
    'tiles'
  ]);
  const featureFlags: FeatureFlags = user?.experiment?.value.scenario.featureFlags;
  const { isButtonHidden, isCounterHidden, isSidebarHidden, isTilesHidden, isDiscovered, clicksPerDay } = contentAds || {};

  if (yieldkitDomains) await removeStorageItems(['yieldkitDomains']);

  if (!featureFlags) return;

  await dOMContentLoaded;

  const colors = isDarkMode() ? theme.dark : theme.light;
  setTheme(colors);

  if (featureFlags.GOOGLE_COUNTER_ON && !isCounterHidden && window.innerWidth >= 1200) {
    chrome.runtime.sendMessage({
      type: 'shellsCounter',
    }, (response) => {
      if (response?.type === 'success') {
        renderCounter(response.shellsCounter || 0);
      }
    });
  }

  if (clicksPerDay?.counter >= 10 && isSameDay(clicksPerDay.when)) return null;

  const query = search.get('q');
  if (featureFlags.GOOGLE_SIDEBAR_ON && !isSidebarHidden) {
    renderSidebar(query, featureFlags);
  }

  const $elements = Array.from(document.querySelectorAll('#search div.g'));

  const urls = $elements.map((search) => {
    const searchTitle = search.querySelector('a > h3');
    if (!searchTitle?.parentElement) return '';

    const { href } = searchTitle.parentElement as HTMLAnchorElement;
    return href;
    // return [href, hostname.replace(/^www\./, '')];
  });

  if (featureFlags.GOOGLE_TILES_ON && !isTilesHidden && window.outerWidth > 1200) {
    renderTiles(query, featureFlags);
  }

  if (!featureFlags.COLLECT_SHELLS_IN_GOOGLE_OFF && !isButtonHidden && annotations) {
    // eslint-disable-next-line no-constant-condition
    // const adMarketplaceListPromise = annotations.adMarketplace
    //   ? fetchAdMarketplace(new URLSearchParams(location.search).get('q'))
    //   : Promise.resolve();

    const digidip = matchDigidip(urls, annotations.digidip);
    const adNet = await matchAdNet(urls, annotations.adNet);

    const lists = [
      adNet,
      matchAdmarketplace(urls, annotations.adMarketplace),
      matchSiteplug(urls, annotations.siteplug, user.userId, digidip),
      (featureFlags.ZP_ANNOTATIONS && zp?.brands) ? matchZeropark(urls, zp) : [],
      digidip,
    ];

    const list = $elements
      .map(($search, index) => {
        const ad = lists
          .filter(Boolean)
          .reduce((acc, provider) => acc || provider[index], null);
        return ad ? [$search, ad] : null;
      })
      .filter(Boolean);

    list.forEach((el, i, arr) => {
      const [$search, ad] = el as SearchTuple;
      renderPreact(
        <Widget
          style={{ zIndex: `${arr.length - i}` }}
          isFirst={i === 0}
          isShellsDiscoveredDefault={isDiscovered}
          ad={ad}
        />,
        $search,
        'annotations'
      );
    });

    if (featureFlags.GOOGLE_ADS_IMPRESSIONS && list.length) {
      chrome.runtime.sendMessage({
        type: 'trackAnalytics',
        events: [
          {
            variant: 'event',
            payload: ['Google ads impression', { type: 'annotations', value: list.length, category: 'Ads' }],
          },
        ],
      });
    }
  }
};

renderWidget();
