export const requestAffinityTiles = async (qt: string): Promise<AdTile[]> => {
  try {
    const result = await fetchData(qt);
    if (!result?.ads?.ad) return null;

    const ads = Array.isArray(result.ads.ad) ? result.ads.ad : [result.ads.ad];
    return ads.map((ad): AdTile => ({
      id: ad.brand,
      title: ad.brand,
      type: 'adTiles',
      url: ad.durl,
      name: ad.brand,
      click_url: ad.impurl,
      image_url: ad.iurl,
      impression_url: ad.impurl,
      provider: 'affinity',
    }));
  } catch (err) {
    console.error('requestAffinityTiles', err);
    return null;
  }
};