import { FunctionalComponent} from 'preact';

import { AnimalIconProps } from '../../interfaces';
import { animalStates } from './utils';
import { awardedShellsAmount } from './utils';
// import {
//   animalStates,
//   awardedShellsAmount,
// } from './utils';

import styles from './styles.module.scss';
import RewardTooltip from '../shared/RewardTooltip';

const AnimalIcon: FunctionalComponent<AnimalIconProps> = ({
                                                            state,
                                                            onClick,
                                                            animalImg,
                                                          }: AnimalIconProps) => {
  return (
    <div className={styles.animalContainer} onClick={onClick}>
      <div className={animalStates[state].styles}>
        <img src={animalImg} alt="Animal" />
      </div>

      {state === animalStates.show.value && (
        <RewardTooltip gain={awardedShellsAmount} />
      )}
    </div>
  );
};

export default AnimalIcon;
