import { FunctionalComponent} from 'preact';
import { useRef, useState } from 'preact/hooks';

import { useOnScreen } from '../../../../shared/hooks/useOnScreen';
import { AdResult, AnimalState, WidgetContainerProps } from '../../interfaces';
import { awardedShellsAmount, animalStates } from './utils';
import { getRandomAnimalImage } from '../../utils';
import ContextMenu from '../shared/ContextMenu';
import { trackGain, openUrl } from '../shared/utils';

import VisitAndCollectShellsButton from './Button';
import VisitAndCollectShellsTooltip from './Tooltip';
import AnimalIcon from './AnimalIcon';

import styles from './styles.module.scss';

const processClick = async (ad: AdResult) => {
  if (ad.provider === 'siteplug') {
    const fallbackUrl = ad.fallback?.clickUrl || ad.url;
    let target = fallbackUrl;
    try {
      const res = await fetch(ad.clickUrl);
      if (res.ok) {
        const json = await res.json();
        target = json.target;
      }
    } catch (err) {
      console.error('fetch:annotations', err);
    }

    openUrl(target || fallbackUrl);
    return;
  }

  setTimeout(() => {
    openUrl(ad.clickUrl);
  }, 700);
};

const WidgetContainer: FunctionalComponent<WidgetContainerProps> = ({
                                                                      ad,
                                                                      isFirst,
                                                                      style,
                                                                      isShellsDiscoveredDefault,
                                                                    }: WidgetContainerProps) => {
  const ref = useRef<HTMLDivElement>();
  const isVisible = useOnScreen(ref);

  const { hide, show, peek } = animalStates;
  const [isShellsDiscovered, setIsShellsDiscovered] = useState(
    isShellsDiscoveredDefault
  );
  const [animalImg, setAnimalImg] = useState(getRandomAnimalImage());
  const [animalState, setAnimalState] = useState<AnimalState>(hide.value);

  const onCloseTooltip = (): void => {
    setIsShellsDiscovered(true);
  };

  const onRedirectHandler = async (): Promise<void> => {
    setAnimalState(show.value);
    trackGain({
      gain: awardedShellsAmount,
      revenue: 0.1,
      provider: ad.provider,
      productId: 'CONTENT_ADS',
      eventName: 'Clicked_collect_shell_button',
    });

    processClick(ad);
  };

  const showAnimal = (): void => {
    if (animalState === hide.value) {
      setAnimalImg(getRandomAnimalImage());
      setAnimalState(peek.value);
    }
  };

  const shouldTooltipRender = (): boolean =>
    isFirst && !isShellsDiscovered && isVisible;

  return (
    <div
      className={styles.placeholder}
      onMouseLeave={(): void => {
        setAnimalState(hide.value);
      }}
      style={style}
      ref={ref}
      data-provider={ad.provider}
      data-href={ad.clickUrl}
      data-testid="oh-widget"
    >
      {ad.impressionUrl && (
        <img className={styles.impressionImg} src={ad.impressionUrl} alt="" />
      )}
      <VisitAndCollectShellsButton
        onMouseEnter={showAnimal}
        onClick={onRedirectHandler}
      />
      <ContextMenu variant="annotations" />
      {shouldTooltipRender() && (
        <VisitAndCollectShellsTooltip onClose={onCloseTooltip} />
      )}

      <AnimalIcon
        state={animalState}
        onClick={onRedirectHandler}
        animalImg={animalImg}
      />
    </div>
  );
};

export default WidgetContainer;
