import { FunctionalComponent, JSX } from 'preact';
import { useEffect, useState } from 'preact/compat';

import { toRuntimeUrl } from '../../../shared/utils';
import { isDarkMode } from '../../utils';

import icon48 from '../../../../public/img/icon48.png';
import icon48White from '../../../../public/img/icon48-white.png';

// import shellBlue from '../../../../public/img/shell-blue.svg';
// import bottleBlue from '../../../../public/img/bottle-blue.svg';

import ContextMenu from '../shared/ContextMenu';

// eventually migrate to https://github.com/pmcalmeida/preact-cli-svg-loader but there are more SVG used as simple imgs so they need to be handled
import Bottle from './Bottle';
import Shell from './Shell';

import styles from './styles.module.scss';

interface Props {
  shellsCounter: number,
  style?: JSX.CSSProperties,
}

const Counter: FunctionalComponent<Props> = ({ shellsCounter, style }: Props) => {
  const [newShells, setNewShells] = useState(0);
  useEffect(() => {
    window.addEventListener('ohGainedShells', (evt: CustomEvent) => {
      setNewShells((prev) => prev + evt.detail.gain);
    });

    const el = window.document.querySelector<HTMLElement>('[action="/search"]');
    if (el) el.style.zIndex = '9999';
  }, []);

  const totalShells = shellsCounter + newShells;
  const bottles = Math.floor(totalShells / 100);
  const remainingShells = totalShells - bottles * 100;

  return (
    <div className={styles.container} style={style}>
      <img src={toRuntimeUrl(isDarkMode() ? icon48White : icon48)} alt="OceanHero" width={20} />

      <Shell style={{ width: 20, marginLeft: 8 }} />
      <span data-testid="shells">{remainingShells}</span>

      <Bottle style={{ width: 20, marginLeft: 8 }} />
      <span data-testid="bottles">{bottles}</span>

      <ContextMenu
        variant="counter"
        size="small"
        style={{ position: 'absolute', right: -26, top: 5 }}
        styleTooltip={{ left: -150, top: 35 }}
      />
    </div>
  );
};

export default Counter;
