export const getRandomNumberInBetween = (min: number, max: number): number =>
  Math.floor(Math.random() * (max - min + 1)) + min;

export const openUrl = (url: string) => {
  chrome.runtime.sendMessage({ type: 'openTab', url });
}

export const trackGain = ({ gain, revenue, productId, provider, eventName }) => {
  const evt = new CustomEvent('ohGainedShells', { detail: { gain }});
  window.dispatchEvent(evt);

  chrome.runtime.sendMessage({
    type: 'contentAdClicked',
    gain,
    events: [
      {
        variant: 'event',
        payload: [
          eventName,
          {
            name: provider,
            category: 'Ads',
            revenue,
            shells_value: gain,
          },
        ],
      },
      {
        variant: 'revenue',
        payload: [
          null,
          {
            productId,
            category: 'Ads',
            quantity: 1,
            price: revenue,
          },
        ],
      },
    ],
  });
}