import { AdResult } from './interfaces';
import { Zeropark } from '../../newtab/features/searchForm/slice/types';

export const matchAdmarketplace = (
  urls: string[],
  annotations: string[]
): (AdResult | null)[] => {
  return urls.map((url) => {
    if (!annotations) return null;

    const found = annotations.find((name) => url.match(name)) || '';

    const clickUrl = (() => {
      try {
        // https://www.amazon.com/apple-iphone/s?k=apple+iphone
        // https://www.amazon.de/-/en/MGJ73ZD-A-Apple-iPhone-12/dp/B08L5VKVGZ <= not handling this
        if (found.match('amazon')) {
          const query = new URLSearchParams(url.split('?')[1]).get('k');
          // if (!query) return null;
          return `https://oceanhero.ampxdirect.com/amazon?${new URLSearchParams({
            sub1: 'amazon',
            sub2: 'serp_dynamic_qt',
            qt: query,
          })}`;
        }

        if (found.match('ebay')) {
          if (url.match('/b/')) {
            const query = url.split('/b/')[1].split('/')[0].split('-').join(' ');
            // if (!query) return null;
            return `https://oceanhero.ampxdirect.com/ebay?${new URLSearchParams({
              sub1:'ebay',
              sub2:'serp_dynamic_qt',
              qt: query,
            })}`;
          }
        }

        // href="https://www.ebay.com/b/Sneakers-for-Men/15709/bn_57918".split('/b/')[1].split('/')[0]
      } catch (err) {
        console.error('matchAdmarketplace', err);
      }

      return null;
    })();

    return clickUrl ? { url, clickUrl, provider: 'adMarketplace' } : null;
  });
};

export const matchDigidip = (urls: string[], annotations: string[]): (AdResult | null)[] => {
  return urls.map((url) => {
    const found = annotations.find((ad) => (ad || '').trim() && url.match(ad));

    return found
      ? {
        url,
        provider: 'digidip',
        clickUrl: `http://oceanhero.digidip.net/visit?url=${url}`,
        impressionUrl: null,
      }
      : null;
  });
}

export const matchZeropark = (urls: string[], zp: Zeropark): (AdResult | null)[] => {
  return urls.map((url) => {
    const found = zp.brands.find((brand) => url.match(brand.brand.url));

    return found
      ? {
        url,
        provider: 'zeropark',
        clickUrl: zp.clickUrl
          .replace(/\${brand.url}/g, found.brand.url)
          .replace(/\${brand.name}/g, found.brand.name),
        impressionUrl: null,
      }
      : null;
  });
}

interface AdNetMatch {
  url: string;
  provider: string;
  clickUrl: string
  impressionUrl: string;
}

export const matchAdNet = (urls: string[], annotations: string[]): Promise<AdNetMatch[]> => {
  const promises = urls.map(async (url) => {
    const found = annotations.find((ad) => url.match(ad));
    if (!found) return null;

    try {
      const query = new URLSearchParams({
        sid: '11173637',
        q: '11173637_oceanhero',
        said: `OH_${found.split('.')[0]}`,
        // client_ip: '198.23.242.152',
        // ...ip && { client_ip: ip },
        mark_url: url,
        fallBackUrl: url,
      });
      const res = await fetch(`https://11173637.p.ad.net/ads?${query}`);

      if (!res.ok) return null;

      const xml = await res.text();

      const parser = new DOMParser();
      const doc = parser.parseFromString(xml, 'text/xml');
      const { textContent } = doc.getElementsByTagName('clickUrl')[0] || {};

      console.log('matchAdNet:innerHTML', textContent);
      return textContent
        ? {
            url,
            provider: 'adNet',
            clickUrl: textContent,
            impressionUrl: null,
          }
        : null;
    } catch (err) {
      console.error('matchAdNet', err);
      return null;
    }
  });

  return Promise.all(promises);
};

export const matchSiteplug = (
  urls: string[],
  annotations: string[],
  userId: string,
  fallbacks: AdResult[]): (AdResult | null)[] => {
    return urls.map((url, i) => {
      const found = annotations.find((ad) => (ad || '').trim() && url.match(ad));

      return found
        ? {
          url,
          provider: 'siteplug',
          clickUrl: `https://oceanhero.today/api/annotations?${new URLSearchParams({
            userId,
            url,
          })}`,
          impressionUrl: null,
          fallback: fallbacks[i],
        }
        : null;
    });
}
