import { renderPreact } from '../../utils';

import { AdMarketplaceLongTailData } from '../../../../newtab/features/searchForm/slice/types';
import { requestAdmarketplaceLongTailSuggestions } from './api';
import SidebarAds from '.';
import { FeatureFlags } from '../../../../newtab/features/user/slice/types';

const renderSidebarAds = async (query, featureFlags: FeatureFlags) => {
  const data = await requestAdmarketplaceLongTailSuggestions(query);
  if (!data?.count || data?.count === '0') return null;

  const $sidebar = document.querySelector(`[role="complementary"]`);
  const $centerCol = document.querySelector('#center_col');

  const component =  <SidebarAds featureFlags={featureFlags} data={data as AdMarketplaceLongTailData} />;

  if ($sidebar) {
    return renderPreact(component, $sidebar, 'sidebar', true);
  }

  if ($centerCol) {
    return renderPreact(component, $centerCol.parentElement, 'sidebar');
  }
};

export default renderSidebarAds;