import { FunctionalComponent} from 'preact';

import { VisitAndCollectShellsTooltipProps } from '../../interfaces';
import { updateContentAds } from '../../utils';
import Tooltip from '../shared/Tooltip';

const VisitAndCollectShellsTooltip: FunctionalComponent<VisitAndCollectShellsTooltipProps> = ({
  onClose,
}: VisitAndCollectShellsTooltipProps) => {
  const handleClose = (e: MouseEvent) => {
    updateContentAds({ isDiscovered: true });
    onClose(e);
  };

  return (
    <Tooltip
      arrow="top"
      onClose={handleClose}
    >Hey! This button will take you to the page AND earn you shells on OceanHero 🐋</Tooltip>
  )
};

export default VisitAndCollectShellsTooltip;
