import { FunctionalComponent } from 'preact';

import answers from './answers.json';
import { toRuntimeUrl } from '../../../../shared/utils';
import { getRandomNumberInBetween } from '../utils';
import styles from './styles.module.scss';

import yellowShell from '../../../../../public/img/yellow-shell.svg';

interface Props {
  gain: number;
  hideArrow?: boolean
  style?: any,
}

const RewardTooltip: FunctionalComponent<Props> = ({ gain, style, hideArrow }: Props) => (
  <div
    className={`${styles.bubble} ${styles.animalSpeechBubble} ${hideArrow ? styles.hideArrow : ''}`}
    style={style}
  >
    {answers[getRandomNumberInBetween(0, answers.length - 1)]}
    <span>+{gain} <img src={toRuntimeUrl(yellowShell)} alt='Shell' /></span>
  </div>
);

export default RewardTooltip;